/*
 * Procurement Materials Platform offline chart compatibility layer.
 * Implements the small Chart.js-compatible API subset used by this prototype:
 * new Chart(ctx, config), destroy(), resize(), data, canvas and external tooltip callbacks.
 * This is NOT the official Chart.js distribution. Replace this file with the official
 * Chart.js UMD build before production if exact Chart.js behavior is required.
 */
(function(global){
  'use strict';
  function finiteNumbers(datasets){
    var vals=[];
    datasets.forEach(function(ds){ (ds.data||[]).forEach(function(v){ v=Number(v); if(Number.isFinite(v)) vals.push(v); }); });
    return vals;
  }
  function compact(v){
    var a=Math.abs(v);
    if(a>=1000000) return (v/1000000).toFixed(a>=10000000?0:1)+'M';
    if(a>=1000) return (v/1000).toFixed(a>=10000?0:1)+'k';
    if(a>=10) return v.toFixed(0);
    return v.toFixed(2);
  }
  function OfflineChart(ctx, config){
    if(!(this instanceof OfflineChart)) return new OfflineChart(ctx, config);
    if(!ctx || !ctx.canvas) throw new Error('A 2D canvas context is required.');
    this.ctx=ctx;
    this.canvas=ctx.canvas;
    this.config=config||{};
    this.data=this.config.data||{labels:[],datasets:[]};
    this.options=this.config.options||{};
    this._hoverIndex=null;
    this._destroyed=false;
    this._onMove=this._handleMove.bind(this);
    this._onLeave=this._handleLeave.bind(this);
    this._onResize=this.resize.bind(this);
    this.canvas.addEventListener('mousemove',this._onMove);
    this.canvas.addEventListener('mouseleave',this._onLeave);
    global.addEventListener('resize',this._onResize);
    this.resize();
  }
  OfflineChart.version='offline-compatible-1.0.0';
  OfflineChart.prototype._size=function(){
    var parent=this.canvas.parentElement;
    var w=Math.max(320,(parent&&parent.clientWidth)||this.canvas.clientWidth||800);
    var h=Math.max(220,(parent&&parent.clientHeight)||this.canvas.clientHeight||360);
    var dpr=Math.max(1,global.devicePixelRatio||1);
    this.canvas.width=Math.round(w*dpr);
    this.canvas.height=Math.round(h*dpr);
    this.canvas.style.width=w+'px';
    this.canvas.style.height=h+'px';
    this.ctx.setTransform(dpr,0,0,dpr,0,0);
    this.width=w; this.height=h; this._dpr=dpr;
  };
  OfflineChart.prototype._geometry=function(){
    var labels=this.data.labels||[], datasets=this.data.datasets||[];
    var vals=finiteNumbers(datasets), min=vals.length?Math.min.apply(null,vals):0, max=vals.length?Math.max.apply(null,vals):1;
    if(min===max){ var delta=Math.abs(min||1)*0.05; min-=delta; max+=delta; }
    var pad=(max-min)*0.08; min-=pad; max+=pad;
    var plot={left:58,top:14,right:this.width-16,bottom:this.height-38};
    plot.width=Math.max(1,plot.right-plot.left); plot.height=Math.max(1,plot.bottom-plot.top);
    var x=function(i){ return plot.left+(labels.length<=1?plot.width/2:(i/(labels.length-1))*plot.width); };
    var y=function(v){ return plot.bottom-((v-min)/(max-min))*plot.height; };
    return {labels:labels,datasets:datasets,min:min,max:max,plot:plot,x:x,y:y};
  };
  OfflineChart.prototype._draw=function(){
    if(this._destroyed) return;
    var c=this.ctx,g=this._geometry(),p=g.plot;
    c.clearRect(0,0,this.width,this.height);
    c.save();
    c.font='10.5px -apple-system, BlinkMacSystemFont, Segoe UI, Arial, sans-serif';
    c.fillStyle='#8695A6'; c.strokeStyle='#EEF1F4'; c.lineWidth=1;
    var ticks=5;
    for(var i=0;i<=ticks;i++){
      var yy=p.top+(p.height*i/ticks), value=g.max-(g.max-g.min)*(i/ticks);
      c.beginPath(); c.moveTo(p.left,yy); c.lineTo(p.right,yy); c.stroke();
      c.textAlign='right'; c.textBaseline='middle'; c.fillText(compact(value),p.left-8,yy);
    }
    var maxLabels=Math.min(8,g.labels.length), step=Math.max(1,Math.ceil(g.labels.length/maxLabels));
    c.textAlign='center'; c.textBaseline='top';
    for(var j=0;j<g.labels.length;j+=step){ c.fillText(String(g.labels[j]),g.x(j),p.bottom+9); }
    if(g.labels.length>1 && (g.labels.length-1)%step!==0){ c.fillText(String(g.labels[g.labels.length-1]),g.x(g.labels.length-1),p.bottom+9); }
    g.datasets.forEach(function(ds){
      var data=ds.data||[]; c.save(); c.strokeStyle=ds.borderColor||'#0B5769'; c.lineWidth=ds.borderWidth||2; c.lineJoin='round'; c.lineCap='round';
      c.beginPath(); var started=false;
      data.forEach(function(v,idx){ v=Number(v); if(!Number.isFinite(v)) return; var xx=g.x(idx),yy=g.y(v); if(!started){c.moveTo(xx,yy);started=true;}else c.lineTo(xx,yy); });
      c.stroke(); c.restore();
    });
    if(this._hoverIndex!==null && g.labels.length){
      var hi=Math.max(0,Math.min(g.labels.length-1,this._hoverIndex)), hx=g.x(hi);
      c.save(); c.strokeStyle='#9AA8B5'; c.setLineDash([3,3]); c.beginPath(); c.moveTo(hx,p.top); c.lineTo(hx,p.bottom); c.stroke(); c.setLineDash([]);
      g.datasets.forEach(function(ds){ var v=Number((ds.data||[])[hi]); if(!Number.isFinite(v)) return; c.beginPath(); c.arc(hx,g.y(v),3.5,0,Math.PI*2); c.fillStyle=ds.borderColor||'#0B5769'; c.fill(); c.lineWidth=2; c.strokeStyle='#fff'; c.stroke(); });
      c.restore();
    }
    c.restore();
  };
  OfflineChart.prototype._tooltipCallback=function(payload){
    var ext=this.options&&this.options.plugins&&this.options.plugins.tooltip&&this.options.plugins.tooltip.external;
    if(typeof ext==='function') ext(payload);
  };
  OfflineChart.prototype._handleMove=function(ev){
    var rect=this.canvas.getBoundingClientRect(), g=this._geometry();
    if(!g.labels.length) return;
    var mx=ev.clientX-rect.left;
    var idx=g.labels.length<=1?0:Math.round((mx-g.plot.left)/g.plot.width*(g.labels.length-1));
    idx=Math.max(0,Math.min(g.labels.length-1,idx));
    this._hoverIndex=idx; this._draw();
    var points=[], ySum=0, yCount=0;
    g.datasets.forEach(function(ds,di){ var raw=Number((ds.data||[])[idx]); if(!Number.isFinite(raw)) return; points.push({datasetIndex:di,dataIndex:idx,raw:raw}); ySum+=g.y(raw); yCount++; });
    this._tooltipCallback({chart:this,tooltip:{opacity:points.length?1:0,caretX:g.x(idx),caretY:yCount?ySum/yCount:g.plot.top,dataPoints:points}});
  };
  OfflineChart.prototype._handleLeave=function(){
    this._hoverIndex=null; this._draw(); this._tooltipCallback({chart:this,tooltip:{opacity:0,dataPoints:[]}});
  };
  OfflineChart.prototype.resize=function(){ if(this._destroyed) return; this._size(); this._draw(); };
  OfflineChart.prototype.destroy=function(){
    if(this._destroyed) return; this._destroyed=true;
    this.canvas.removeEventListener('mousemove',this._onMove); this.canvas.removeEventListener('mouseleave',this._onLeave); global.removeEventListener('resize',this._onResize);
    this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);
  };
  global.Chart=OfflineChart;
})(typeof window!=='undefined'?window:this);
